"""Dialogue script parser — converts script.txt into a JSON graph and DOT visualization."""

import json
import re
from typing import Dict, List, Optional, Tuple


def parse_script(text: str) -> Dict:
    """Parse a dialogue script and return a graph dict with nodes and edges."""
    lines = text.splitlines()
    nodes: Dict[str, dict] = {}
    edges: List[dict] = []

    current_section: Optional[str] = None
    in_section = False

    # First pass: identify all section headers as nodes
    # Determine section type: "choice" if it contains numbered options, "line" otherwise
    # We need two passes: first collect raw content per section, then determine types.

    raw_sections: Dict[str, List[str]] = {}
    active_section: Optional[str] = None

    for line in lines:
        header_match = re.match(r'^\[(.+?)\]$', line.strip())
        if header_match:
            active_section = header_match.group(1)
            if active_section not in raw_sections:
                raw_sections[active_section] = []
            continue
        if active_section and line.strip():
            raw_sections[active_section].append(line.strip())

    # Second pass: process each section
    for section_id, section_lines in raw_sections.items():
        all_choice = all(
            re.match(r'^\d+\.\s', l) for l in section_lines
        )

        if all_choice:
            node_type = "choice"
            speaker = ""
            text = ""
            nodes[section_id] = {
                "id": section_id,
                "text": text,
                "speaker": speaker,
                "type": node_type,
            }
            for line_text in section_lines:
                # Parse: N. [Skill] text -> Target
                m = re.match(
                    r'^(\d+)\.\s(?:\[(.+?)\]\s)?(.+?)\s*->\s*(\S+)$',
                    line_text,
                )
                if m:
                    num = m.group(1)
                    skill = m.group(2)
                    raw_text = m.group(3).strip()
                    target = m.group(4)

                    if skill:
                        edge_text = f"{num}. [{skill}] {raw_text}"
                    else:
                        edge_text = f"{num}. {raw_text}"

                    edges.append({
                        "from": section_id,
                        "to": target,
                        "text": edge_text,
                    })
        else:
            node_type = "line"
            # Merge all lines for this section (usually one line, but could be multiple)
            combined_text = " ".join(section_lines)
            # Parse: Speaker: text -> Target
            m = re.match(
                r'^(.+?):\s+(.+?)\s*->\s*(\S+)$',
                combined_text,
            )
            if m:
                speaker = m.group(1).strip()
                raw_text = m.group(2).strip()
                target = m.group(3)

                nodes[section_id] = {
                    "id": section_id,
                    "text": raw_text,
                    "speaker": speaker,
                    "type": node_type,
                }
                edges.append({
                    "from": section_id,
                    "to": target,
                    "text": "",
                })
            else:
                # Fallback: section with content but no proper format
                nodes[section_id] = {
                    "id": section_id,
                    "text": combined_text,
                    "speaker": "",
                    "type": "line",
                }

    return {"nodes": list(nodes.values()), "edges": edges}


def validate_graph(graph: Dict) -> List[str]:
    """Validate graph constraints. Returns list of error messages."""
    errors: List[str] = []
    node_ids = {n["id"] for n in graph["nodes"]}
    edges = graph["edges"]

    if not graph["nodes"]:
        errors.append("No nodes found")
        return errors

    first_node = graph["nodes"][0]["id"]

    # Build adjacency for reachability check
    adj: Dict[str, List[str]] = {nid: [] for nid in node_ids}
    for e in edges:
        adj.setdefault(e["from"], []).append(e["to"])

    # (1) All nodes must be reachable from the first node
    visited: set = set()
    stack = [first_node]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in visited and nxt in node_ids:
                stack.append(nxt)

    unreachable = node_ids - visited
    if unreachable:
        errors.append(
            f"Unreachable nodes from '{first_node}': {sorted(unreachable)}"
        )

    # (2) All edge targets must exist except "End"
    for e in edges:
        target = e["to"]
        if target != "End" and target not in node_ids:
            errors.append(
                f"Edge target '{target}' (from '{e['from']}') does not exist"
            )

    return errors


def generate_dot(graph: Dict) -> str:
    """Generate a Graphviz DOT representation of the dialogue graph."""
    lines = ["digraph Dialogue {", '  rankdir=TB;']
    lines.append('  node [shape=box, style=rounded];')

    for node in graph["nodes"]:
        nid = node["id"]
        ntype = node["type"]
        speaker = node.get("speaker", "")
        text = node.get("text", "")

        if ntype == "choice":
            color = "lightyellow"
            label_text = f"{nid}\\n(Choice)"
        else:
            color = "lightblue"
            short_text = text[:50] + "..." if len(text) > 50 else text
            label_text = f"{speaker}: {short_text}" if speaker else text[:50]

        label_text = label_text.replace('"', '\\"')
        lines.append(
            f'  "{nid}" [label="{label_text}", fillcolor={color}, style="filled,rounded"];'
        )

    # Add "End" as a special node if referenced
    end_refs = any(e["to"] == "End" for e in graph["edges"])
    if end_refs:
        lines.append(
            '  "End" [label="End", fillcolor=lightgreen, style="filled,rounded"];'
        )

    for e in graph["edges"]:
        edge_text = e["text"].replace('"', '\\"')
        if edge_text:
            lines.append(
                f'  "{e["from"]}" -> "{e["to"]}" [label="{edge_text}"];'
            )
        else:
            lines.append(f'  "{e["from"]}" -> "{e["to"]}";')

    lines.append("}")
    return "\n".join(lines)


def main():
    with open("/app/script.txt", "r") as f:
        text = f.read()

    graph = parse_script(text)

    # Validate
    errors = validate_graph(graph)
    if errors:
        print("VALIDATION ERRORS:")
        for err in errors:
            print(f"  - {err}")
    else:
        print("Validation passed!")

    # Write JSON
    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)
    print("Wrote /app/dialogue.json")

    # Write DOT
    dot = generate_dot(graph)
    with open("/app/dialogue.dot", "w") as f:
        f.write(dot)
    print("Wrote /app/dialogue.dot")

    print(f"Nodes: {len(graph['nodes'])}, Edges: {len(graph['edges'])}")


if __name__ == "__main__":
    main()", "path": "/app/solution.py"}: Editing /app/solution.py

